#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Lane C Twilio WhatsApp Sandbox, Render & Live Alert Proof Wizard
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "GuardianLine Lane C Setup: Twilio WhatsApp Sandbox, Render & Live Alert Proof"

# ── Stage 1: Twilio Credentials & WhatsApp Sandbox ─────────────────────────
stage "Twilio Console: Account SID, Auth Token & WhatsApp Sandbox"
say "Grab your Twilio Account SID, Auth Token, and WhatsApp Sandbox number."
open_url "https://console.twilio.com/us1/develop/sms/try-it-out/whatsapp-learn"
step "In the Twilio Console Account Info panel, copy your Account SID (starts with AC)."
ask TWILIO_ACCOUNT_SID "Paste TWILIO_ACCOUNT_SID:"
step "Copy your Auth Token from the Account Info panel."
ask_secret TWILIO_AUTH_TOKEN "Paste TWILIO_AUTH_TOKEN:"
step "On the 'Try WhatsApp' page, note the Twilio Sandbox number (default +14155238886) and join code."
ask TWILIO_WHATSAPP_FROM "Enter TWILIO_WHATSAPP_FROM (e.g. +14155238886):"
[[ -z "$TWILIO_WHATSAPP_FROM" ]] && TWILIO_WHATSAPP_FROM="+14155238886"

write_env TWILIO_ACCOUNT_SID "$TWILIO_ACCOUNT_SID"
write_env TWILIO_AUTH_TOKEN "$TWILIO_AUTH_TOKEN"
write_env TWILIO_WHATSAPP_FROM "$TWILIO_WHATSAPP_FROM"
write_env ALERT_CHANNEL "whatsapp"

# ── Stage 2: Join WhatsApp Sandbox on Every Test Phone ─────────────────────
stage "Test Phones: Send the WhatsApp Sandbox Join Code"
say "Every family recipient phone must join the Twilio WhatsApp Sandbox before alerts can arrive."
step "On each test phone, open WhatsApp and message $TWILIO_WHATSAPP_FROM with your sandbox join code (e.g. 'join <word>-<word>')."
step "Wait for Twilio's reply confirming 'Twilio Sandbox: ✅ You are all set!'."
ask FAMILY_ALERT_TO "Enter comma-separated recipient E.164 phone numbers (e.g. +919876543210):"
write_env FAMILY_ALERT_TO "$FAMILY_ALERT_TO"
pause "Press Enter once all test phones have received the Twilio Sandbox confirmation reply"

# ── Stage 3: Configure Render Environment Variables ────────────────────────
stage "Render Dashboard: Set Twilio WhatsApp Sandbox Credentials"
say "Put the Twilio WhatsApp Sandbox credentials on the Render guardianline-backend service."
open_url "https://dashboard.render.com"
step "Open 'guardianline-backend' -> 'Environment'."
step "Set TWILIO_ACCOUNT_SID = $TWILIO_ACCOUNT_SID"
step "Set TWILIO_AUTH_TOKEN = (your Twilio Auth Token)"
step "Set TWILIO_WHATSAPP_FROM = $TWILIO_WHATSAPP_FROM"
step "Set ALERT_CHANNEL = whatsapp"
step "Set FAMILY_ALERT_TO = $FAMILY_ALERT_TO"
ask REPORT_BASE_URL "Enter your Render REPORT_BASE_URL (e.g. https://guardianline-backend.onrender.com/dashboard/report):"
[[ -z "$REPORT_BASE_URL" ]] && REPORT_BASE_URL="http://localhost:8000/dashboard/report"
write_env REPORT_BASE_URL "$REPORT_BASE_URL"
pause "Press Enter after saving the environment variables on Render"

# ── Stage 4: Deliver One Real WhatsApp Alert & Capture Proof ───────────────
stage "Live Alert Proof: Deliver Real WhatsApp Alert & Capture SID + Screenshot"
say "Now we will dispatch one real WhatsApp alert and record the Twilio Message SID (SM...)."
ask SCREENSHOT_PATH "Where will you save the WhatsApp screenshot? (default: evaluation/live_calls/whatsapp_alert_screenshot.png):"
[[ -z "$SCREENSHOT_PATH" ]] && SCREENSHOT_PATH="evaluation/live_calls/whatsapp_alert_screenshot.png"
if confirm "Send the live WhatsApp alert now using scripts/send_test_alert.py?"; then
  python scripts/send_test_alert.py --screenshot "$SCREENSHOT_PATH" || warn "Alert delivery failed; inspect credentials and re-run."
  step "Take a screenshot of the delivered WhatsApp message on your test phone and save it to: $SCREENSHOT_PATH"
  pause "Press Enter once the screenshot is saved"
else
  SKIPPED+=("Run: python scripts/send_test_alert.py --screenshot $SCREENSHOT_PATH")
fi

# ── Stage 5: Optional Carrier Test 1 (Only if a Physical SIM is Available) ─
stage "Optional Carrier Test 1 (Physical SIM Only)"
say "Only run Carrier Test 1 if you can borrow a physical Indian SIM card. Otherwise leave evaluation/carrier_results.json as NOT_VERIFIED."
step "If testing on a physical SIM, dial **67*<BOLNA_GATEWAY_NUMBER># and **61*<BOLNA_GATEWAY_NUMBER>**15#."
step "IMPORTANT: Dial ##002# immediately afterwards to undo all conditional call forwarding."
pause "Press Enter to finish"

finish
